1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type QuoteStep = {
9	  op: "quote";
10	  items: Item[];
11	};
12	
13	export type Scenario = {
14	  customer: { yearsWithMHPCO: number };
15	  steps: QuoteStep[];
16	};
17	
18	export type ScenarioResults = {
19	  results: unknown[];
20	};
21	
22	const PROCESSING_FEE = 5;
23	const FIRST_INSURANCE_SURCHARGE = 0.1;
24	const CURSE_SURCHARGE = 0.5;
25	const HIGH_ENCHANTMENT_THRESHOLD = 5;
26	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
27	
28	const ITEM_BASE_PREMIUMS: Record<string, number> = {
29	  sword: 100,
30	  amulet: 60,
31	  staff: 80,
32	  potion: 40,
33	  rune: 25,
34	  moonstone: 25,
35	};
36	
37	const roundInMHPCOsFavour = (premium: number): number => Math.ceil(premium);
38	
39	const BLOCK_SIZE = 3;
40	const BLOCK_BASE_PREMIUM = 60;
41	
42	const countByType = (items: Item[]): Map<string, number> => {
43	  const counts = new Map<string, number>();
44	  for (const item of items) {
45	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
46	  }
47	  return counts;
48	};
49	
50	const basePremiumForGroup = (type: string, count: number): number =>
51	  count === BLOCK_SIZE
52	    ? BLOCK_BASE_PREMIUM
53	    : count * ITEM_BASE_PREMIUMS[type];
54	
55	const calculatePolicyBasePremium = (items: Item[]): number =>
56	  [...countByType(items)].reduce(
57	    (total, [type, count]) => total + basePremiumForGroup(type, count),
58	    0,
59	  );
60	
61	const itemSurcharges = (item: Item): number => {
62	  const itemBasePremium = ITEM_BASE_PREMIUMS[item.type];
63	  const curse = item.cursed ? itemBasePremium * CURSE_SURCHARGE : 0;
64	  const highEnchantment =
65	    (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD
66	      ? itemBasePremium * HIGH_ENCHANTMENT_SURCHARGE
67	      : 0;
68	  return curse + highEnchantment;
69	};
70	
71	const sumItemSurcharges = (items: Item[]): number =>
72	  items.reduce((sum, item) => sum + itemSurcharges(item), 0);
73	
74	const quotePremium = (items: Item[]): number => {
75	  const policyBasePremium = calculatePolicyBasePremium(items);
76	  return roundInMHPCOsFavour(
77	    policyBasePremium +
78	      sumItemSurcharges(items) +
79	      policyBasePremium * FIRST_INSURANCE_SURCHARGE +
80	      PROCESSING_FEE,
81	  );
82	};
83	
84	export const runScenario = (scenario: Scenario): ScenarioResults => {
85	  return {
86	    results: scenario.steps.map((step) => ({ premium: quotePremium(step.items) })),
87	  };
88	};
